import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    d = [int(next(it)) for _ in range(m)]
    g = int(next(it))
    r = int(next(it))

    d.sort()
    idx = {x: i for i, x in enumerate(d)}

    INF = 10**18
    dist = [[INF] * (g + 1) for _ in range(m)]
    dist[0][0] = 0

    dq = deque()
    dq.append((0, 0))

    while dq:
        i, t = dq.popleft()
        cur = dist[i][t]
        if t == g:
            nt = 0
            if dist[i][nt] > cur + r:
                dist[i][nt] = cur + r
                dq.append((i, nt))
            continue

        for j in (i - 1, i + 1):
            if 0 <= j < m:
                w = abs(d[j] - d[i])
                if t + w <= g:
                    nt = t + w
                    if dist[j][nt] > cur + w:
                        dist[j][nt] = cur + w
                        if w == 0:
                            dq.appendleft((j, nt))
                        else:
                            dq.append((j, nt))

    ans = INF
    target = idx[n]
    for t in range(g + 1):
        if dist[target][t] < INF:
            ans = min(ans, dist[target][t])

    if ans == INF:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    main()
